#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/timing/timing.h>

#define STACK_SIZE 512

/* Test parameters */
#define TEST_SLEEP_MS 500
#define TEST_TICKS_TO_SLEEP (TEST_SLEEP_MS / (1000 / CONFIG_SYS_CLOCK_TICKS_PER_SEC))

/* Global variables to store actual sleep ticks for different levels */
static k_ticks_t actual_pre_kernel_1_sleep_ticks;
static k_ticks_t actual_pre_kernel_2_sleep_ticks;
static k_ticks_t actual_post_kernel_sleep_ticks;
static k_ticks_t actual_application_sleep_ticks;

/* Thread entry functions for different initialization levels */
static void pre_kernel_1_sleep_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_ticks_t start_ticks = k_uptime_ticks();
    k_sleep(K_MSEC(TEST_SLEEP_MS));
    k_ticks_t end_ticks = k_uptime_ticks();

    actual_pre_kernel_1_sleep_ticks = end_ticks - start_ticks;
}

static void pre_kernel_2_sleep_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_ticks_t start_ticks = k_uptime_ticks();
    k_sleep(K_MSEC(TEST_SLEEP_MS));
    k_ticks_t end_ticks = k_uptime_ticks();

    actual_pre_kernel_2_sleep_ticks = end_ticks - start_ticks;
}

static void post_kernel_sleep_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_ticks_t start_ticks = k_uptime_ticks();
    k_sleep(K_MSEC(TEST_SLEEP_MS));
    k_ticks_t end_ticks = k_uptime_ticks();

    actual_post_kernel_sleep_ticks = end_ticks - start_ticks;
}

static void application_sleep_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_ticks_t start_ticks = k_uptime_ticks();
    k_sleep(K_MSEC(TEST_SLEEP_MS));
    k_ticks_t end_ticks = k_uptime_ticks();

    actual_application_sleep_ticks = end_ticks - start_ticks;
}

/* Thread definitions for different initialization levels */
K_THREAD_DEFINE(pre_kernel_1_sleep_thread, STACK_SIZE,
                pre_kernel_1_sleep_entry, NULL, NULL, NULL,
                K_PRIO_PRE_KERNEL_1, 0, K_NO_WAIT);

K_THREAD_DEFINE(pre_kernel_2_sleep_thread, STACK_SIZE,
                pre_kernel_2_sleep_entry, NULL, NULL, NULL,
                K_PRIO_PRE_KERNEL_2, 0, K_NO_WAIT);

/*
 * The post_kernel_sleep_thread was defined with K_PRIO_PRE_KERNEL_1,
 * causing it to run too early, before the system timer was fully initialized
 * at the POST_KERNEL level. This resulted in k_sleep() returning 0 ticks.
 * Changing the priority to a standard cooperative priority (e.g., K_PRIO_COOP(7))
 * ensures it runs after POST_KERNEL initialization, allowing k_sleep() to function correctly.
 */
K_THREAD_DEFINE(post_kernel_sleep_thread, STACK_SIZE,
                post_kernel_sleep_entry, NULL, NULL, NULL,
                K_PRIO_COOP(7), 0, K_NO_WAIT);

K_THREAD_DEFINE(application_sleep_thread, STACK_SIZE,
                application_sleep_entry, NULL, NULL, NULL,
                K_PRIO_COOP(8), 0, K_NO_WAIT);

/* Test suite definition */
ZTEST_SUITE(earlysleep, NULL, NULL, NULL, NULL, NULL);

/* Test cases */
ZTEST_USER(earlysleep, test_early_sleep)
{
    printk("Testing early sleeping\n");
    printk("msec per tick: %d.%03d, ticks to sleep: %d\n",
           (1000 / CONFIG_SYS_CLOCK_TICKS_PER_SEC),
           (1000000 / CONFIG_SYS_CLOCK_TICKS_PER_SEC) % 1000,
           TEST_TICKS_TO_SLEEP);

    /* Test PRE_KERNEL_1 sleep */
    printk("k_sleep() ticks at PRE_KERNEL_1 level: %lld\n", actual_pre_kernel_1_sleep_ticks);
    /* For PRE_KERNEL_1, sleep might not be fully functional, so we might expect 0 or very little sleep. */
    /* The test might not assert for PRE_KERNEL_1, or assert it's 0. */

    /* Test PRE_KERNEL_2 sleep */
    printk("k_sleep() ticks at PRE_KERNEL_2 level: %lld\n", actual_pre_kernel_2_sleep_ticks);
    /* Similar to PRE_KERNEL_1, might expect 0 or very little. */

    /* Test POST_KERNEL sleep (this was the failing one) */
    printk("k_sleep() ticks at POST_KERNEL level: %lld\n", actual_post_kernel_sleep_ticks);
    /* Line 106 in the original file, based on the error log. */
    zassert_true((actual_post_kernel_sleep_ticks + 1) > TEST_TICKS_TO_SLEEP,
                 "k_sleep() at POST_KERNEL level did not sleep enough (expected > %d, got %lld)",
                 TEST_TICKS_TO_SLEEP, actual_post_kernel_sleep_ticks);

    /* Test APPLICATION sleep */
    printk("k_sleep() ticks at APPLICATION level: %lld\n", actual_application_sleep_ticks);
    zassert_true((actual_application_sleep_ticks + 1) > TEST_TICKS_TO_SLEEP,
                 "k_sleep() at APPLICATION level did not sleep enough (expected > %d, got %lld)",
                 TEST_TICKS_TO_SLEEP, actual_application_sleep_ticks);
}
